import { Controller, Get, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 미리보기 대상 확장자 (hwp·doc·docx·xls·xlsx·ppt·pptx)
const PREVIEW_EXTENSIONS = ['hwp', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx'];
// 가정: 다운로드 권한 판단은 업로더 본인 또는 아래 역할만 허용한다
const DOWNLOAD_ROLES = ['관리자'];
// 가정: ECM 파일 본문은 DB에 없으므로 ECM 참조(ecm_ref)를 파일 내용 값으로 돌려준다
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

@Controller('api/v1')
export class FnSfr03105Controller {
  @Get('/attachments')
  async listAttachments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const targetType = query['targetType'];
    const targetIdRaw = query['targetId'];
    if (typeof targetType !== 'string' || targetType === '' || targetType.length > 50) {
      throw new ApiError(400, 'VALIDATION_FAILED', '업무 대상 유형을 입력해 주세요.');
    }
    if (targetIdRaw === undefined || targetIdRaw === null || String(targetIdRaw) === '' || !/^\d+$/.test(String(targetIdRaw))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '업무 대상 ID는 숫자여야 합니다.');
    }
    const pageRaw = query['page'];
    const sizeRaw = query['size'];
    let page = 0;
    let size = DEFAULT_SIZE;
    if (pageRaw !== undefined && pageRaw !== '') {
      if (!/^\d+$/.test(String(pageRaw))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호는 0 이상의 숫자여야 합니다.');
      }
      page = Number(pageRaw);
    }
    if (sizeRaw !== undefined && sizeRaw !== '') {
      if (!/^\d+$/.test(String(sizeRaw)) || Number(sizeRaw) < 1) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기는 1 이상의 숫자여야 합니다.');
      }
      size = Math.min(Number(sizeRaw), MAX_SIZE);
    }
    return transaction(async (db) => {
      const params = {
        targetType: targetType,
        targetId: String(targetIdRaw),
        userId: user.id,
        limit: size,
        offset: page * size,
      };
      const countRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM attachment WHERE target_type = :targetType AND target_id = CAST(:targetId AS bigint)',
        params,
      );
      const rows = await db.query(
        'SELECT attachment_id AS "attachmentId", file_name AS "fileName", file_extension AS "fileExtension", file_size AS "fileSize", (uploader_id = CAST(:userId AS bigint)) AS "isOwner" FROM attachment WHERE target_type = :targetType AND target_id = CAST(:targetId AS bigint) ORDER BY attachment_id LIMIT :limit OFFSET :offset',
        params,
      );
      const isAdmin = DOWNLOAD_ROLES.some((r) => user.has(r));
      const items = rows.map((r: any) => {
        const ext = String(r.fileExtension ?? '').toLowerCase();
        return {
          attachmentId: Number(r.attachmentId),
          fileName: r.fileName,
          fileExtension: r.fileExtension,
          fileSize: r.fileSize === null ? null : Number(r.fileSize),
          downloadAllowed: Boolean(r.isOwner) || isAdmin,
          previewAvailable: PREVIEW_EXTENSIONS.includes(ext),
        };
      });
      return {
        items,
        page,
        size,
        total: Number(countRows[0]?.total ?? 0),
      };
    });
  }

  @Get('/attachments/:attachmentId/download')
  async downloadAttachment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const idText = req.params['attachmentId'];
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '첨부파일 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT ecm_ref AS "ecmRef", (uploader_id = CAST(:userId AS bigint)) AS "isOwner" FROM attachment WHERE attachment_id = CAST(:id AS bigint)',
        { id: idText, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTACHMENT_NOT_FOUND', '첨부파일을 찾을 수 없습니다.');
      }
      const row: any = rows[0];
      const isAdmin = DOWNLOAD_ROLES.some((r) => user.has(r));
      if (!(Boolean(row.isOwner) || isAdmin)) {
        throw new ApiError(422, 'DOWNLOAD_NOT_ALLOWED', '다운로드 권한이 없습니다. 미리보기만 볼 수 있습니다.');
      }
      // 가정: ECM 연계 전까지 ECM 참조 값(없으면 빈 문자열)을 파일 내용 자리에 돌려준다
      return { file: row.ecmRef ?? '' };
    });
  }
}

