import { useState } from 'react';
import { Band, Badge, DataTable, Field, Filters, Form, NumberInput, Pager, TextInput, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

export default function FnSfr03105Page({ role, notify }: PageProps) {
  const [targetType, setTargetType] = useState('');
  const [targetId, setTargetId] = useState<number | string>('');
  const [applied, setApplied] = useState<{ targetType: string; targetId: number | string } | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [fileContent, setFileContent] = useState<string | null>(null);
  const [selected, setSelected] = useState<Row | null>(null);

  const list = useData<Page | null>(
    async () => {
      if (!applied) {
        return null;
      }
      return call<Page>('GET', '/attachments', role, undefined, {
        targetType: applied.targetType,
        targetId: applied.targetId,
        page: pageNo,
        size: 20,
      });
    },
    [applied, pageNo, role],
  );

  function search() {
    if (targetType === '' || targetId === '') {
      notify('업무 대상 유형과 ID를 입력해 주세요.');
      return;
    }
    setPageNo(0);
    setApplied({ targetType, targetId });
  }

  function reset() {
    setTargetType('');
    setTargetId('');
    setApplied(null);
    setPageNo(0);
    setSelected(null);
    setFileContent(null);
  }

  const rows = list.data ? list.data.items : [];

  if (selected) {
    return (
      <div className="doc">
        <button className="ghost" onClick={() => { setSelected(null); setFileContent(null); }}>
          목록으로
        </button>
        <section className="box">
          <h2>첨부파일 내려받기</h2>
          <p>{String(selected['fileName'])} 파일을 내려받습니다.</p>
          {fileContent !== null && <TextInput value={fileContent} onChange={() => {}} multiline />}
          <Form
            submit="다운로드"
            onSubmit={async () => {
              const res = await call<Row>('GET', '/attachments/' + String(selected['attachmentId']) + '/download', role);
              setFileContent(String(res['file'] ?? ''));
              notify('다운로드했습니다.');
            }}
          >
            <Field label="파일명">
              <span>{String(selected['fileName'])}</span>
            </Field>
          </Form>
        </section>
      </div>
    );
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>첨부파일 조회</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="업무 대상 유형" required>
            <TextInput value={targetType} onChange={setTargetType} />
          </Field>
          <Field label="업무 대상 ID" required>
            <NumberInput value={targetId} onChange={setTargetId} />
          </Field>
        </Filters>
      </section>
      <section className="box">
        <h2>첨부파일 목록</h2>
        {list.error !== '' && <p>{list.error}</p>}
        <Band total={list.data ? list.data.total : 0} />
        <DataTable
          columns={[
            { key: 'fileName', label: '파일명' },
            { key: 'fileExtension', label: '확장자' },
            { key: 'fileSize', label: '파일 크기(바이트)' },
            {
              key: 'downloadAllowed',
              label: '다운로드',
              render: (row) => <Badge value={row['downloadAllowed'] ? '허용' : '미리보기만'} />,
            },
            {
              key: 'previewAvailable',
              label: '미리보기',
              render: (row) => <Badge value={row['previewAvailable'] ? '가능' : '불가'} />,
            },
          ]}
          rows={rows}
          onRowClick={(row) => {
            if (row['downloadAllowed']) {
              setSelected(row);
            } else {
              notify('다운로드 권한이 없어 미리보기만 제공됩니다.');
            }
          }}
          empty={applied ? '조건에 맞는 첨부파일이 없습니다.' : '업무 대상 유형과 ID를 입력해 조회해 보세요.'}
        />
        {list.data && (
          <Pager page={list.data.page} size={list.data.size} total={list.data.total} onPage={setPageNo} />
        )}
      </section>
    </div>
  );
}
